changeSet.sql:
CREATE TABLE comments ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id BIGINT NOT NULL, profile_id BIGINT NOT NULL, parent_id BIGINT, text VARCHAR(2200) NOT NULL, likes_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ,
CONSTRAINT COMMENTS_POST_FK FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE, CONSTRAINT COMMENTS_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE, CONSTRAINT COMMENTS_PARENT_FK FOREIGN KEY (parent_id) REFERENCES comments(id) ON DELETE CASCADE );
CREATE INDEX idx_comments_post ON comments(post_id, created_at) WHERE deleted_at IS NULL; CREATE INDEX idx_comments_profile ON comments(profile_id) WHERE deleted_at IS NULL; CREATE INDEX idx_comments_parent ON comments(parent_id) WHERE parent_id IS NOT NULL AND deleted_at IS NULL;
